#!/usr/bin/env python3
"""
installer_moteur_plans_v1.py — Installe le moteur de plans (2 fichiers)
  1. app/api/moteur_plans.py   (nouveau module admin)
  2. data/plans_pays_v1.json   (base de faits vérifiée 2026-07-13)
Auto-vérifiant : SHA-256 + ast.parse + json.loads. Idempotent.
Usage : python3 installer_moteur_plans_v1.py
"""
import ast, base64, hashlib, json, sys
from pathlib import Path

RACINE = Path.home() / "mobilite-ia"

FICHIERS = {
    "app/api/moteur_plans.py": {
        "sha256": "d1023111adfd4d8ef671feb10d3efaf8d5afac03d97b7f7a6d5e9d7d27c426e6",
        "b64": "",
        "verif": "python",
    },
    "data/plans_pays_v1.json": {
        "sha256": "23642285e763bab61f0b307f21364584cfe7aaf0165701e5074463faddbb9376",
        "b64": "",
        "verif": "json",
    },
}

def main():
    if not RACINE.exists():
        sys.exit(f"❌ Projet introuvable : {RACINE}")
    for rel, info in FICHIERS.items():
        cible = RACINE / rel
        data = base64.b64decode(info["b64"])
        if hashlib.sha256(data).hexdigest() != info["sha256"]:
            sys.exit(f"❌ Empreinte invalide pour {rel} — fichier corrompu, abandon.")
        if info["verif"] == "python":
            ast.parse(data.decode("utf-8"))
        else:
            kb = json.loads(data.decode("utf-8"))
            assert len(kb["destinations"]["IT"]["groupe1"]["pays"]) == 38
            assert len(kb["destinations"]["BE"]["pays_eligibles"]) == 31
        if cible.exists():
            if cible.read_bytes() == data:
                print(f"ℹ️  {rel} — identique, déjà en place.")
                continue
            bak = cible.with_name(cible.name + ".bak-installe")
            cible.rename(bak)
            print(f"⚠️  {rel} existait (différent) → sauvegardé : {bak.name}")
        cible.parent.mkdir(parents=True, exist_ok=True)
        cible.write_bytes(data)
        print(f"✅ Installé : {rel} ({len(data)} octets, empreinte vérifiée)")
    print()
    print("Moteur installé. PROCHAINE ÉTAPE : le branchement dans ui.py")
    print("(une ligne d'import + une ligne admin) — patch séparé à venir.")
    print("Test direct sans branchement :")
    print("  cd ~/mobilite-ia && python3 -c \"import sys; sys.path.insert(0,'app/api'); import moteur_plans; print('module OK')\"")

if __name__ == "__main__":
    main()
